#!/usr/bin/env node
// Independent check of the phone ↔ hub contract vectors (docs/CONTRACTS.md §10).
//
// The vectors in docs/contracts/vectors.json are generated by the iOS unit tests
// (CryptoKit). This script recomputes every value with Node's built-in `crypto`
// only, the same library the bridge uses, and fails loudly on any mismatch.
// It is the reference the bridge and relay builders can copy.
//
// Usage: node tools/contracts/verify-vectors.mjs [path/to/vectors.json]
// Exit code 0 = every vector matches; 1 = a mismatch or a malformed file.

import crypto from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const file = process.argv[2] ?? path.join(here, '..', '..', 'docs', 'contracts', 'vectors.json');

// ---- helpers ---------------------------------------------------------------
const b64u = {
  dec: (s) => Buffer.from(s.replace(/-/g, '+').replace(/_/g, '/'), 'base64'),
  enc: (b) => Buffer.from(b).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''),
};
const PKCS8_X25519_PREFIX = Buffer.from('302e020100300506032b656e04220420', 'hex');

function privateKeyFromRaw(raw) {
  return crypto.createPrivateKey({ key: Buffer.concat([PKCS8_X25519_PREFIX, raw]), format: 'der', type: 'pkcs8' });
}
function publicRawFromPrivate(priv) {
  return b64u.dec(crypto.createPublicKey(priv).export({ format: 'jwk' }).x);
}
function publicKeyFromRaw(raw) {
  // [L1] Node imports a raw X25519 public key most reliably as a JWK.
  return crypto.createPublicKey({ key: { kty: 'OKP', crv: 'X25519', x: b64u.enc(raw) }, format: 'jwk' });
}
function x25519(privRaw, pubRaw) {
  const shared = crypto.diffieHellman({ privateKey: privateKeyFromRaw(privRaw), publicKey: publicKeyFromRaw(pubRaw) });
  if (shared.every((byte) => byte === 0)) throw new Error('all-zero shared secret');
  return shared;
}
const hkdf = (ikm, salt, info, len) => Buffer.from(crypto.hkdfSync('sha256', ikm, salt, Buffer.from(info, 'ascii'), len));
const hmac = (key, msg) => crypto.createHmac('sha256', key).update(msg).digest();

function proofInput(phonePub, role, name) {
  return Buffer.concat([phonePub, Buffer.from(role, 'ascii'), Buffer.from([0]), Buffer.from(name.normalize('NFC'), 'utf8')]);
}
function pairingCode(shared, secret) {
  const four = hkdf(shared, secret, 'debbie/v1/code', 4);
  return String(four.readUInt32BE(0) % 10000).padStart(4, '0');
}
function seal(key, nonce, ad, plaintext) {
  const cipher = crypto.createCipheriv('chacha20-poly1305', key, nonce, { authTagLength: 16 });
  cipher.setAAD(ad, { plaintextLength: plaintext.length });
  return Buffer.concat([cipher.update(plaintext), cipher.final(), cipher.getAuthTag()]);
}
function open(key, nonce, ad, c) {
  const decipher = crypto.createDecipheriv('chacha20-poly1305', key, nonce, { authTagLength: 16 });
  decipher.setAAD(ad, { plaintextLength: c.length - 16 });
  decipher.setAuthTag(c.subarray(c.length - 16));
  return Buffer.concat([decipher.update(c.subarray(0, c.length - 16)), decipher.final()]);
}
const adFor = (homeId, kid, type) => Buffer.from(kid === 'pair' ? 'debbie/v1/pair' : `debbie/v1/${homeId}/${kid}/${type}`, 'ascii');

// ---- run ---------------------------------------------------------------------
let failures = 0;
let checks = 0;
function expectEqual(label, actual, expected) {
  checks += 1;
  const a = Buffer.isBuffer(actual) ? b64u.enc(actual) : String(actual);
  if (a !== expected) {
    failures += 1;
    console.error(`FAIL ${label}\n  expected ${expected}\n  actual   ${a}`);
  }
}

let vectors;
try {
  vectors = JSON.parse(readFileSync(file, 'utf8'));
} catch (err) {
  console.error(`cannot read ${file}: ${err.message}`);
  process.exit(1);
}

for (const v of vectors.x25519 ?? []) {
  const phonePriv = b64u.dec(v.phone_private);
  const hubPriv = b64u.dec(v.hub_private);
  expectEqual(`x25519[${v.name}].phone_public`, publicRawFromPrivate(privateKeyFromRaw(phonePriv)), v.phone_public);
  expectEqual(`x25519[${v.name}].hub_public`, publicRawFromPrivate(privateKeyFromRaw(hubPriv)), v.hub_public);
  expectEqual(`x25519[${v.name}].shared (phone side)`, x25519(phonePriv, b64u.dec(v.hub_public)), v.shared);
  expectEqual(`x25519[${v.name}].shared (hub side)`, x25519(hubPriv, b64u.dec(v.phone_public)), v.shared);
}

for (const v of vectors.pairing ?? []) {
  const secret = b64u.dec(v.secret);
  const phonePub = b64u.dec(v.phone_public);
  const shared = b64u.dec(v.shared);
  expectEqual(`pairing[${v.name}].proof`, hmac(secret, proofInput(phonePub, v.role, v.device_name)), v.proof);
  expectEqual(`pairing[${v.name}].phone_key`, hkdf(shared, secret, 'debbie/v1/phone-key', 32), v.phone_key);
  expectEqual(`pairing[${v.name}].code`, pairingCode(shared, secret), v.code);
}

for (const v of vectors.envelopes ?? []) {
  const key = b64u.dec(v.key);
  const nonce = b64u.dec(v.nonce);
  const ad = adFor(v.home_id, v.kid, v.type);
  expectEqual(`envelope[${v.name}].ad`, ad.toString('ascii'), v.ad);
  const c = seal(key, nonce, ad, Buffer.from(v.plaintext, 'utf8'));
  expectEqual(`envelope[${v.name}].c`, c, v.envelope.c);
  expectEqual(`envelope[${v.name}].n`, nonce, v.envelope.n);
  expectEqual(`envelope[${v.name}].kid`, v.envelope.kid, v.kid);
  expectEqual(`envelope[${v.name}].decrypts`, open(key, nonce, ad, b64u.dec(v.envelope.c)).toString('utf8'), v.plaintext);
  // Tampering must fail: relabelling the type changes the associated data (except during pairing,
  // whose associated data is the constant "debbie/v1/pair"), and a flipped ciphertext byte fails the tag.
  checks += 1;
  try {
    if (v.kid === 'pair') {
      const c = Buffer.from(b64u.dec(v.envelope.c)); c[0] ^= 1;
      open(key, nonce, ad, c);
    } else {
      open(key, nonce, adFor(v.home_id, v.kid, v.type === 'alert' ? 'status' : 'alert'), b64u.dec(v.envelope.c));
    }
    failures += 1;
    console.error(`FAIL envelope[${v.name}] opened after tampering`);
  } catch {
    // expected
  }
}

for (const v of vectors.credential_hash ?? []) {
  expectEqual(`credential_hash`, crypto.createHash('sha256').update(v.credential, 'utf8').digest('hex'), v.sha256_hex);
}

if (checks === 0) {
  console.error('no vectors found');
  process.exit(1);
}
console.log(`${checks - failures}/${checks} checks passed (${file})`);
process.exit(failures === 0 ? 0 : 1);
